            .bind(&record.updated_at)
            .bind(&record.id)
            .execute(&mut *connection)
            .await?;
        }
    }
    read_object_result(connection, &record.id).await
}

/// Admit one canonical object mutation atomically with its envelope.
/// Device registration/trust and policy-version enforcement belong to later tickets.
/// Replay equality is deliberately defined over `record.payload` alone. A replay
/// reads the recorded target's current state; the ledger is not historical state.
pub async fn admit_object(
    pool: &SqlitePool,
    envelope: &MutationEnvelope,
    record: NewObjectRecord,
) -> Result<ObjectRecord> {
    let mut transaction = crate::transactions::begin(pool).await?;
    let result = async {
        let prepared = prepare_mutation(
            &mut transaction,
            envelope,
            &record.payload,
            MutationTarget::Object,
        )
        .await?;
        admit_prepared_object(&mut transaction, envelope, record, prepared).await
    }
    .await;
    finish_mutation(transaction, result).await
}

/// Complete ordinary object admission on an already prepared transaction.
/// Candidate admission composes this exact path with its candidate/event writes;
/// only the outer public writer owns commit or rollback.
pub(crate) async fn admit_prepared_object(
    connection: &mut SqliteConnection,
    envelope: &MutationEnvelope,
    record: NewObjectRecord,
    prepared: PreparedMutation,
) -> Result<ObjectRecord> {
    if let Some(replay) = prepared.replay {
        return read_object_result(connection, &replay.result_object_id).await;
    }
    let admitted = write_object_row(connection, envelope, record).await?;
    record_mutation(
        connection,
        envelope,
        &prepared.canonical_payload,
        &admitted.id,
        admitted.version,
    )
    .await?;
    Ok(admitted)
}

/// Append a canonical fact. The log id needs no object-version precondition;
/// all supplied read preconditions are enforced. Replay compares record.payload.
pub async fn append_log_entry(
    pool: &SqlitePool,
    envelope: &MutationEnvelope,
    record: NewLogRecord,
) -> Result<LogRecord> {
    let mut transaction = crate::transactions::begin(pool).await?;
    let result = async {
        let prepared = prepare_mutation(
            &mut transaction,
            envelope,
            &record.payload,
            MutationTarget::Log,
        )
        .await?;
        append_prepared_log(&mut transaction, envelope, record, prepared).await
    }
    .await;
    finish_mutation(transaction, result).await
}

/// Complete Log admission on the transaction owned by the outer writer.
pub(crate) async fn append_prepared_log(
    connection: &mut SqliteConnection,
    envelope: &MutationEnvelope,
    record: NewLogRecord,
    prepared: PreparedMutation,
) -> Result<LogRecord> {
    if let Some(replay) = prepared.replay {
        return sqlx::query_as::<_, LogRecord>("SELECT * FROM logs WHERE id = ?")
            .bind(replay.result_object_id)
            .fetch_one(&mut *connection)
            .await
            .map_err(Into::into);
    }
    validate_object_id_for_type(&record.id, ObjectType::LogEntry.as_str())?;
    validate_provenance_json(&record.provenance)?;
    if record.event_type == "recalculation_requested" {
        validate_recalculation_trigger_payload(&record.payload)?;
    }
    UbuTimestamp::parse(&record.created_at)?;
    let object_refs_json = serde_json::to_string(&record.object_refs)?;
    let payload_json = serde_json::to_string(&record.payload)?;
    let provenance_json = serde_json::to_string(&record.provenance)?;

    sqlx::query(
        "INSERT INTO logs
    (id, event_type, object_refs_json, payload_json, provenance_json, created_at)
    VALUES (?, ?, ?, ?, ?, ?)",
    )
    .bind(&record.id)
    .bind(&record.event_type)
    .bind(&object_refs_json)
    .bind(&payload_json)
    .bind(&provenance_json)
    .bind(&record.created_at)
    .execute(&mut *connection)
    .await?;

    record_mutation(
        connection,
        envelope,
        &prepared.canonical_payload,
        &record.id,
        0,
    )
    .await?;

    sqlx::query_as::<_, LogRecord>("SELECT * FROM logs WHERE id = ?")
        .bind(&record.id)
        .fetch_one(&mut *connection)
        .await
        .map_err(Into::into)
}

/// One canonical write inside a batch. Each write carries its own envelope:
/// the ledger is keyed by `(origin_device_id, idempotency_key)` and one key
/// records exactly one result object.
#[derive(Debug, Clone)]
pub enum BatchWrite {
    Object {
        envelope: MutationEnvelope,
        record: NewObjectRecord,
    },
    Log {
        envelope: MutationEnvelope,
        record: NewLogRecord,
    },
}

/// The admitted result of one `BatchWrite`, in request order.
#[derive(Debug, Clone)]
pub enum BatchResult {
    Object(ObjectRecord),
    Log(LogRecord),
}

impl BatchResult {
    pub fn as_object(&self) -> Option<&ObjectRecord> {
        match self {
            Self::Object(record) => Some(record),
            Self::Log(_) => None,
        }
    }
    pub fn as_log(&self) -> Option<&LogRecord> {
        match self {
            Self::Log(record) => Some(record),
            Self::Object(_) => None,
        }
    }
}

