fn accept_observation(external_id: &str, observed: &[DesiredEvent], applied: &mut [DesiredEvent]) {
    if let (Some(old), Some(current)) = (
        applied.iter_mut().find(|e| e.external_id == external_id),
        observed.iter().find(|e| e.external_id == external_id),
    ) {
        *old = current.clone();
    }
}

/// Keep phone-completed events available for the bounded undo gesture, even
/// after regeneration removes the Task or an old plan still contains it.
pub async fn preserve_completed(
    pool: &sqlx::SqlitePool,
    desired: &mut Vec<DesiredEvent>,
    applied: &[DesiredEvent],
) -> Result<()> {
    let owned = observed_owned(pool, applied, applied).await?;
    for item in owned {
        if (!item.is_static || item.routine_objective_id.is_some())
            && !item.is_captured
            && item.status == "completed"
            && item.latest_completion.as_ref().is_some_and(|completion| {
                completion.is_from_calendar_event(&item.event.external_id)
            })
        {
            desired.retain(|event| event.task_id != item.task_id);
            desired.push(item.event);
        }
    }
    desired.sort_by(|a, b| (&a.start_at, &a.external_id).cmp(&(&b.start_at, &b.external_id)));
    Ok(())
}


async fn apply_move(state: &AppState, signal: &MoveSignal) -> Result<Vec<DiagnosticBody>> {
    if let Some(task) = queries::get_current_state(state.inner().store.pool(), &signal.task_id).await? {
        let payload: Value = serde_json::from_str(&task.payload_json).map_err(internal)?;
        if let Some((objective, date)) = payload["occurrence"]["routine_objective_id"].as_str().zip(payload["occurrence"]["local_date"].as_str()) {
            let window = CalendarTimeRange::parse(&signal.new_start, &signal.new_end)
                .map_err(|_| AppError::bad_request_diagnostic("routine_override_invalid_window", "Override window must have a strictly positive span"))?;
            let result = super::routine_override::change(state, objective, date, Some((window.start, window.end)), Some(super::routine_override::CalendarSource {
                task_id: &signal.task_id, external_id: &signal.external_id,
            })).await?;
            return Ok(result.diagnostics);
        }
    }

/// A Task has effects when it lists at least one mutation. One with no `effects`,
/// or with none listed, has nothing to apply and nothing to say about it.
fn has_effects(task: &TaskForTransition) -> bool {
    task.payload["effects"]["mutations"].as_array().is_some_and(|mutations| !mutations.is_empty())
}

async fn apply_completed_effects(
    state: &AppState,
    task: &TaskForTransition,
    authority_source: AuthoritySource,
    mode: InstanceMode,
    effective_time: UbuTimestamp,
) -> Result<Vec<ActionDiagnostic>> {
    let pool = state.inner().store.pool();
    let Some(effects_value) = task.payload.get("effects") else {
        return Ok(Vec::new());
    };
    let effect: TaskEffect = serde_json::from_value(effects_value.clone())
        .map_err(|e| AppError::Internal(format!("failed to deserialize task effects: {e}")))?;

    // `success_probability` is intentionally ignored: completion, not the
    // predicted probability, is what makes the effect apply.
    if effect.mutations.is_empty() {
        return Ok(Vec::new());
    }

    // Mode validation: an intrinsic-affect mutation target under a mode that
    // does not model intrinsic affect makes the effect invalid (surfaced
    // distinctly); `user_mode` always permits.
    if let Err(error) = validate_mutations_for_mode(mode, &effect.mutations) {
        return Ok(vec![ActionDiagnostic {
            code: "task_effect_mode_invalid".to_owned(),
            message: error.to_string(),
        }]);
    }

    let current = planning_service::read_current_universe_state(pool).await?;
    let (current_state, current_version) = if let Some(current) = current {
        current
    } else {
        let seed = UniverseState::new(effective_time, "empty UniverseState seeded on Task completion");
        let now = effective_time.to_string();
        let mut payload = serde_json::to_value(&seed)
            .map_err(|e| AppError::Internal(e.to_string()))?;
        payload["schema_version"] = json!("core/universe-state/0.1");
        payload["provenance"] = json!({"created_at":effective_time,"authority_source":authority_source});
        let envelope = state.envelope_for(
            [
                (seed.id.clone(), VersionRef::Absent),
                (UbuId::parse(&task.id)?, observed_version(task.version)?),
            ].into_iter().collect(),
            authority_source,
            effective_time,
        )?;
        queries::admit_object(pool, &envelope, NewObjectRecord {
            id: seed.id.to_string(),
            object_type: ObjectType::UniverseState.as_str().into(),
            version: 1,
            status: "active".into(),
            compartment_label: task.compartment_label.clone(),
            payload,
            created_at: now.clone(),
            updated_at: now,
        }).await?;
        planning_service::read_current_universe_state(pool).await?
            .ok_or_else(|| AppError::Internal("UniverseState missing after seed admission".into()))?
    };

    let next_state = match apply_universe_mutations(&current_state, &effect.mutations, effective_time) {
        Ok(next_state) => next_state,
        Err(error) => {
            return Ok(vec![ActionDiagnostic {
                code: "task_effect_application_failed".to_owned(),
                message: error.to_string(),
            }]);
        }
    };

